def solution(stream):
    lines = stream.split('\n')
    lines.pop()               # text after the last newline is an unfinished line
    events = []
    name = 'message'
    data = []
    for line in lines:
        if line == '':
            # blank line: dispatch, but only if the event had data
            if data:
                events.append([name, '\n'.join(data)])
            name, data = 'message', []
            continue
        if line.startswith(':'):
            continue          # comment, often used as a keep-alive
        if ':' in line:
            field, value = line.split(':', 1)
            if value.startswith(' '):
                value = value[1:]   # remove exactly one leading space
        else:
            field, value = line, ''
        if field == 'data':
            if value == '[DONE]':
                break         # end of stream; the unfinished event is dropped
            data.append(value)
        elif field == 'event':
            name = value or 'message'
        # any other field (id, retry, ...) is ignored
    return events

