def solution(stream):
    # Character by character: build each line by hand, handle it when its newline arrives.
    events = []
    name = 'message'
    data = []
    line = ''
    for ch in stream:
        if ch != '\n':
            line = line + ch
            continue
        if line == '':
            if len(data) > 0:
                joined = data[0]
                for piece in data[1:]:
                    joined = joined + '\n' + piece
                events.append([name, joined])
            name = 'message'
            data = []
        elif line[0] != ':':
            idx = line.find(':')
            if idx == -1:
                field = line
                value = ''
            else:
                field = line[:idx]
                value = line[idx + 1:]
                if len(value) > 0 and value[0] == ' ':
                    value = value[1:]
            if field == 'data':
                if value == '[DONE]':
                    return events
                data.append(value)
            elif field == 'event':
                if value == '':
                    name = 'message'
                else:
                    name = value
        line = ''
    return events
